"""Shell completions: scripts generated by `focal completions`, and the legacy scripts in
completions/, which complete command names through `focal --commands`."""

import os
import shutil
import subprocess
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
CLI = Path(os.environ.get("FOCAL_TEST_BIN", ROOT / "bin/focal")).resolve()
LEGACY = "FOCAL_TEST_BIN" not in os.environ
COMMANDS = [
    "api",
    "ci-fail",
    "context",
    "diff",
    "files",
    "issues",
    "pr-diff",
    "release-context",
    "search",
    "symbol",
    "tree",
    "web",
    "wip-context",
]
BASH = shutil.which("bash")
ZSH = shutil.which("zsh")
# Generation is new in the Rust binary; the legacy dispatcher reports an unknown command.
generated = pytest.mark.xfail(
    LEGACY, reason="legacy ships static completion scripts only", strict=True
)


def run(tmp_path, *args):
    path = "" if os.environ.get("FOCAL_TEST_EMPTY_PATH") else os.environ["PATH"]
    return subprocess.run(
        [CLI, *args],
        cwd=tmp_path,
        env={"PATH": path, "HOME": str(tmp_path), "NO_COLOR": "1", "LC_ALL": "C"},
        capture_output=True,
        stdin=subprocess.DEVNULL,
        check=False,
    )


def script(tmp_path, shell):
    result = run(tmp_path, "completions", shell)
    assert result.returncode == 0, result.stderr.decode()
    assert result.stderr == b""
    path = tmp_path / f"focal.{shell}"
    path.write_bytes(result.stdout)
    return path


def complete_bash(tmp_path, script_path, function, *words):
    """Sources a Bash completion script with `focal` on PATH and completes the last word.

    The function receives the command, current word, and previous word, as `complete -F`
    passes them, and the candidates come back one per line."""
    if BASH is None:
        pytest.skip("bash is not installed")
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir(exist_ok=True)
    link = bin_dir / "focal"
    if not link.exists():
        link.symlink_to(CLI)
    path = str(bin_dir)
    if not os.environ.get("FOCAL_TEST_EMPTY_PATH"):
        path += os.pathsep + os.environ["PATH"]
    words = ("focal", *words)
    program = (
        'source "$1"; shift; COMP_WORDS=("$@"); COMP_CWORD=$(($# - 1));'
        f' {function} focal "${{COMP_WORDS[COMP_CWORD]}}"'
        ' "${COMP_WORDS[COMP_CWORD - 1]}";'
        ' for c in "${COMPREPLY[@]}"; do echo "$c"; done'
    )
    result = subprocess.run(
        [BASH, "--norc", "--noprofile", "-c", program, "bash", script_path, *words],
        cwd=tmp_path,
        env={"PATH": path, "HOME": str(tmp_path), "LC_ALL": "C"},
        capture_output=True,
        check=False,
    )
    assert result.returncode == 0, result.stderr.decode()
    return result.stdout.decode().split()


@generated
@pytest.mark.parametrize("shell", ["bash", "zsh"])
def test_generated_script_names_every_public_command(tmp_path, shell):
    text = script(tmp_path, shell).read_text()
    for name in COMMANDS:
        assert name in text, name
    assert "completions" not in text
    for flag in ("--staged", "--cached", "--thick", "--modified", "--repo"):
        assert flag in text, flag


@generated
def test_generated_bash_script_parses(tmp_path):
    if BASH is None:
        pytest.skip("bash is not installed")
    path = script(tmp_path, "bash")
    result = subprocess.run([BASH, "-n", path], capture_output=True, check=False)
    assert result.returncode == 0, result.stderr.decode()


@generated
def test_generated_zsh_script_parses(tmp_path):
    if ZSH is None:
        pytest.skip("zsh is not installed")
    path = script(tmp_path, "zsh")
    result = subprocess.run([ZSH, "-n", path], capture_output=True, check=False)
    assert result.returncode == 0, result.stderr.decode()
    assert path.read_text().startswith("#compdef focal\n")


@generated
@pytest.mark.parametrize(
    ("words", "expected"),
    [
        (("",), COMMANDS),
        (("wi",), ["wip-context"]),
        (("diff", "--st"), ["--staged"]),
        (("files", "--mo"), ["--modified"]),
        (("--repo", "https://github.com/o/r", "tr"), ["tree"]),
    ],
)
def test_generated_bash_script_completes(tmp_path, words, expected):
    candidates = complete_bash(tmp_path, script(tmp_path, "bash"), "_focal", *words)
    # An empty word also offers the top-level flags; the order follows the parser.
    if not words[-1]:
        candidates = [c for c in candidates if not c.startswith("-")]
    assert sorted(candidates) == expected


@generated
@pytest.mark.parametrize("shell", ["fish", ""])
def test_unknown_shell_is_rejected(tmp_path, shell):
    result = run(tmp_path, "completions", shell)
    assert result.returncode == 1
    assert result.stdout == b""
    assert f"unsupported shell '{shell}'" in result.stderr.decode()


@pytest.mark.parametrize(("word", "expected"), [("", COMMANDS), ("pr", ["pr-diff"])])
def test_legacy_bash_script_completes_through_commands_flag(tmp_path, word, expected):
    candidates = complete_bash(
        tmp_path, ROOT / "completions/focal.bash", "_focal_completions", word
    )
    assert candidates == expected
